     curve([[0,.12,-1.13],[.38,.17,-1.11],[.80,.27,-1.03],[span,.20,-.85]],.10,'iron');
     curve([[-span,.20,-.85],[-.69,.12,-.65],[0,.13,.36],[.69,.12,-.65],[span,.20,-.85]],.012,'wrap');
     rod([0,.30,-1.14],[0,.30,.52],.025,'steel');
